      "explanation": "\"Security groups create an outbound rule for every inbound rule.\" Not completely right. Statefull\ndoes NOT mean that if you create an inbound (or outbound) rule, it will create an outbound (or\ninbound) rule. What it does mean is: suppose you create an inbound rule on port 443 for the X ip.\nWhen a request enters on port 443 from X ip, it will allow traffic out for that request in the port 443.\nHowever, if you look at the outbound rules, there will not be any outbound rule on port 443 unless\nexplicitly create it. In ACLs, which are stateless, you would have to create an inbound rule to allow\nincoming requests and an outbound rule to allow your application responds to those incoming\nrequests.\n\nes Akses aman ke EC2 instance di private subnet dilakukan dengan membatasi Security Group bastion host hanya dari IP publik perusahaan, dan membatasi Security Group instance aplikasi hanya dari Security Group / IP privat bastion host.\n\n🔗 AWS Documentation & Solution Guide: https://docs.aws.amazon.com/vpc/latest/userguide/VPC_SecurityGroups.html#SecurityGroupRul",
