      "explanation": "In Static Websites, Web pages are returned by the server which are prebuilt.\nThey use simple languages such as HTML, CSS, or JavaScript.\nThere is no processing of content on the server (according to the user) in Static Websites. Web\npages are returned by the server with no change therefore, static Websites are fast.\nThere is no interaction with databases.\nAlso, they are less costly as the host does not need to support server-side processing with different\nlanguages.\n============\nIn Dynamic Websites, Web pages are returned by the server which are processed during runtime\nmeans they are not prebuilt web pages but they are built during runtime according to the user's\ndemand.\nThese use server-side scripting languages such as PHP, Node.js, ASP.NET and many more\nsupported by the server.\nSo, they are slower than static websites but updates and interaction with databases are possible. Solusi terbaik untuk skenario ini adalah opsi (B): 'Create an Amazon S3 bucket and host the website there'. Opsi ini mengikuti AWS Well-Architected Framework untuk keandalan, performa, dan efisiensi biaya.\n\n🔗 AWS Documentation & Solution Guide: https://aws.amazon.com/architecture/well-architected/",
