      "answerLetter": "B",
      "explanation": "Rate limit\nFor a rate-based rule, enter the maximum number of requests to allow in any five-minute period\nfrom an IP address that matches the rule's conditions. The rate limit must be at least 100.\nYou can specify a rate limit alone, or a rate limit and conditions. If you specify only a rate limit, AWS\nWAF places the limit on all IP addresses. If you specify a rate limit and conditions, AWS WAF\nplaces the limit on IP addresses that match the conditions.\nWhen an IP address reaches the rate limit threshold, AWS WAF applies the assigned action (block\nor count) as quickly as possible, usually within 30 seconds. Once the action is in place, if five\nminutes pass with no requests from the IP address, AWS WAF resets the counter to zero.\n\n91 Solusi terbaik untuk skenario ini adalah opsi (B): 'Deploy AWS WAF, associate it with the ALB, and configure a rate-limiting rule.'. Opsi ini mengikuti AWS Well-Architected Framework untuk keandalan, performa, dan efisiensi biaya.\n\n🔗 AWS Documentation & Solution Guide: https://aws.amazon.com/architecture/well-architected/",
